import { z } from "zod";
import { BoundingBox } from "./citation.js";
import type { OcrPage } from "./boxMatch.js";

/**
 * The committed-map wire contract + its boundary parser. A `*.ocr.json` map is a build-time
 * artifact (generated by `scripts/generate-ocr-maps.mjs` from a fixture raster, a reviewed
 * golden) that the box-match reads offline in CI — so no OCR runs on the graded path
 * (`docs/decisions/w2-ocr-engine.md`, `w2-eval-gate`). Loading a file is a boundary, so the raw
 * JSON is `parse`d into a typed `OcrPage` at the edge (parse-don't-validate, typescript-standards).
 */

/** One recognized word and its [0,1]-normalized box. Mirrors the `OcrWord` shape `boxMatch` consumes. */
const OcrWordSchema = z.object({
  text: z.string(),
  box: BoundingBox,
});

/** The OCR word map for a single page. */
const OcrPageSchema = z.object({
  words: z.array(OcrWordSchema),
});

/**
 * Parse a raw committed OCR map (already JSON-decoded) into a validated {@link OcrPage}.
 *
 * **Throws** on malformed input (non-object, out-of-[0,1] coordinate, `page < 1`, missing
 * `text`). A corrupt or hand-edited committed map is a repo-integrity failure — fail loud
 * rather than return a silent empty map, which would degrade every value to `unverified`
 * (`w2-document-ingestion-writes`: never a silent fill). An empty `words` list is valid data.
 */
export function parseOcrMap(raw: unknown): OcrPage {
  return OcrPageSchema.parse(raw);
}

/**
 * Validate an assembled {@link OcrPage} (e.g. one built by the live OCR adapter) against the
 * same schema the committed-map path uses — so the live path is **fail-loud on a malformed box**
 * (NaN, out-of-[0,1], `page < 1`), symmetric with the offline path, not just valid-by-luck.
 * Throws on malformed input.
 */
export function parseOcrPage(raw: unknown): OcrPage {
  return OcrPageSchema.parse(raw);
}
